document.querySelectorAll('.menu-toggle').forEach((toggle)=>{const header=toggle.closest('.site-header');const nav=header?.querySelector('.site-nav');if(!nav)return;toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('is-open',!open)});nav.querySelectorAll('a').forEach((link)=>link.addEventListener('click',()=>{toggle.setAttribute('aria-expanded','false');nav.classList.remove('is-open')}))});
const mobileActions=document.querySelector('.mobile-actions');if(mobileActions){const syncMobileActions=()=>{const shouldShow=window.innerWidth<=700&&window.scrollY>120;mobileActions.classList.toggle('is-visible',shouldShow)};syncMobileActions();window.addEventListener('scroll',syncMobileActions,{passive:true});window.addEventListener('resize',syncMobileActions)}
